class VersionedKV:
    def __init__(self):
        self._working = {}
        self._history = []

    def set(self, key, value) -> None:
        self._working[key] = value

    def delete(self, key) -> None:
        if key not in self._working:
            raise KeyError(key)
        del self._working[key]

    def get(self, key):
        if key not in self._working:
            raise KeyError(key)
        return self._working[key]

    def has(self, key) -> bool:
        return key in self._working

    def commit(self) -> int:
        self._history.append(dict(self._working))
        return len(self._history)

    def get_at(self, key, version):
        if not (1 <= version <= self.latest()):
            raise ValueError(version)
        snap = self._history[version - 1]
        if key not in snap:
            raise KeyError(key)
        return snap[key]

    def rollback(self, version) -> None:
        if not (0 <= version <= self.latest()):
            raise ValueError(version)
        if version == 0:
            self._working = {}
        else:
            self._working = dict(self._history[version - 1])

    def latest(self) -> int:
        return len(self._history)

class UndoStack:
    def __init__(self):
        self._stack = []
        self._history = []

    def push(self, x) -> None:
        self._stack.append(x)
        self._history.append(('push', x))

    def pop(self):
        if not self._stack:
            raise IndexError
        value = self._stack.pop()
        self._history.append(('pop', value))
        return value

    def peek(self):
        if not self._stack:
            raise IndexError
        return self._stack[-1]

    def undo(self) -> None:
        if not self._history:
            raise RuntimeError
        op, value = self._history.pop()
        if op == 'push':
            self._stack.pop()
        else:
            self._stack.append(value)

    def __len__(self) -> int:
        return len(self._stack)

