    n = len(seq)
    if n < 2:
        return 0
    arr = seq[:]

    def sort_and_count(l: int, r: int) -> int:
        if r - l <= 1:
            return 0
        m = (l + r) // 2
        count = sort_and_count(l, m) + sort_and_count(m, r)
        i = l
