def top_k_frequent(items, k):
    if not isinstance(items, list):
        raise TypeError("items must be a list")
    if isinstance(k, bool) or not isinstance(k, int):
        raise TypeError("k must be an int")
    if k < 0:
        raise ValueError("k must be >= 0")
    if k == 0:
        return []
    counts = {}
    order = []
    for x in items:
        if x not in counts:
            counts[x] = 0
            order.append(x)
        counts[x] += 1
    remaining = list(order)
    limit = k
    if len(remaining) < limit:
        limit = len(remaining)
    result = []
    for _ in range(limit):
        best_i = 0
        best_v = remaining[0]
        best_c = counts[best_v]
        for i in range(1, len(remaining)):
            v = remaining[i]
            c = counts[v]
            if c > best_c:
                best_i = i
                best_v = v
                best_c = c
        result.append((best_v, best_c))
        remaining.pop(best_i)
    return result

import collections

def count_stable_windows(readings: list[int], tol: int) -> int:
    n = len(readings)
    if n == 0:
        return 0
    maxd = collections.deque()
    mind = collections.deque()
    left = 0
    count = 0
    for right in range(n):
        while maxd and readings[maxd[-1]] <= readings[right]:
            maxd.pop()
        maxd.append(right)
        while mind and readings[mind[-1]] >= readings[right]:
            mind.pop()
        mind.append(right)
        while readings[maxd[0]] - readings[mind[0]] > tol:
            left += 1
            if maxd and maxd[0] < left:
                maxd.popleft()
            if mind and mind[0] < left:
                mind.popleft()
        count += right - left + 1
    return count

