class TaskScheduler:
    def __init__(self):
        self._heap = []
        self._tasks = {}
        self._seq = 0
        self._count = 0

    def submit(self, task_id, priority):
        if task_id in self._tasks:
            raise ValueError("task already active")
        seq = self._seq
        self._seq += 1
        version = 0
        self._tasks[task_id] = (priority, seq, version)
        heapq.heappush(self._heap, (-priority, seq, task_id, version))
        self._count += 1

    def reprioritize(self, task_id, priority):
        if task_id not in self._tasks:
            raise KeyError(task_id)
        _, seq, version = self._tasks[task_id]
        version += 1
        self._tasks[task_id] = (priority, seq, version)
        heapq.heappush(self._heap, (-priority, seq, task_id, version))

    def cancel(self, task_id):
        if task_id not in self._tasks:
            raise KeyError(task_id)
        del self._tasks[task_id]
        self._count -= 1

    def _purge(self):
        while self._heap:
            neg_p, seq, tid, ver = self._heap[0]
            info = self._tasks.get(tid)
            if info is not None and info[2] == ver:
                break
            heapq.heappop(self._heap)

    def pop(self):
        self._purge()
        if not self._heap:
            raise IndexError("pop from empty scheduler")
        _, _, tid, _ = heapq.heappop(self._heap)
        del self._tasks[tid]
        self._count -= 1
        return tid

    def peek(self):
        self._purge()
        if not self._heap:
            raise IndexError("peek from empty scheduler")
        return self._heap[0][2]

    def priority_of(self, task_id):
        if task_id not in self._tasks:
            raise KeyError(task_id)
        return self._tasks[task_id][0]

    def __len__(self):
        return self._count

