def deep_get(data, path):
    if not isinstance(path, str):
        raise TypeError("path must be a string")
    if path == "":
        raise ValueError("path must not be empty")
    segments = path.split(".")
    def check_empty(segs):
        if len(segs) == 0:
            return None
        if segs[0] == "":
            raise ValueError("empty segment")
        return check_empty(segs[1:])
    check_empty(segments)
    def all_digits(s):
        if len(s) == 0:
            return False
        if s[0] < "0" or s[0] > "9":
            return False
        if len(s) == 1:
            return True
        return all_digits(s[1:])
    def valid_index(s):
        if len(s) == 0:
            return False
        if s[0] == "-":
            return all_digits(s[1:])
        return all_digits(s)
    def go(node, segs):
        if len(segs) == 0:
            return node
        seg = segs[0]
        rest = segs[1:]
        if isinstance(node, dict):
            if seg not in node:
                raise KeyError(seg)
            return go(node[seg], rest)
        if isinstance(node, list):
            if not valid_index(seg):
                raise ValueError("invalid index")
            idx = int(seg)
            if idx >= len(node) or idx < -len(node):
                raise IndexError(seg)
            return go(node[idx], rest)
        raise TypeError("cannot descend")
    return go(data, segments)

def eval_rpn(tokens):
    if not isinstance(tokens, list):
        raise TypeError("tokens must be a list")
    if tokens == []:
        raise ValueError("empty expression")

    def is_operand(s):
        if not s:
            return False
        i = 0
        if s[0] in '+-':
            if len(s) == 1:
                return False
            i = 1
        if i >= len(s):
            return False
        for c in s[i:]:
            if c < '0' or c > '9':
                return False
        return True

    def div_toward_zero(a, b):
        q = a // b
        if a % b != 0 and ((a < 0) != (b < 0)):
            q += 1
        return q

    stack = []
    ops = {'+', '-', '*', '/'}

    for i, tok in enumerate(tokens):
        if not isinstance(tok, str):
            raise TypeError("token {0}".format(i))
        if tok in ops:
            if len(stack) < 2:
                raise ValueError("stack underflow at token {0}".format(i))
            right = stack.pop()
            left = stack.pop()
            if tok == '+':
                stack.append(left + right)
            elif tok == '-':
                stack.append(left - right)
            elif tok == '*':
                stack.append(left * right)
            else:
                if right == 0:
                    raise ZeroDivisionError("token {0}".format(i))
                stack.append(div_toward_zero(left, right))
        elif is_operand(tok):
            stack.append(int(tok))
        else:
            raise ValueError("unknown token token {0}".format(i))

    if len(stack) != 1:
        raise ValueError("leftover operands")
    return stack[0]

def render_template(template, context):
    if not isinstance(template, str):
        raise TypeError("template must be a string")
    if not isinstance(context, dict):
        raise TypeError("context must be a dict")
    result = []
    i = 0
    n = len(template)
    while i < n:
        c = template[i]
        if c == '{':
            if i + 1 < n and template[i + 1] == '{':
                result.append('{')
                i += 2
                continue
            p = i
            i += 1
            if i >= n:
                raise ValueError("unclosed placeholder at position {0}".format(p))
            if template[i] == '}':
                raise ValueError("empty placeholder at position {0}".format(p))
            name_chars = []
            while i < n and template[i] != '}':
                ch = template[i]
                if not (('A' <= ch <= 'Z') or ('a' <= ch <= 'z') or ('0' <= ch <= '9') or ch == '_'):
                    raise ValueError("invalid placeholder at position {0}".format(p))
                name_chars.append(ch)
                i += 1
            if i >= n:
                raise ValueError("unclosed placeholder at position {0}".format(p))
            name = ''.join(name_chars)
            if name not in context:
                raise KeyError(name)
            result.append(str(context[name]))
            i += 1
        elif c == '}':
            if i + 1 < n and template[i + 1] == '}':
                result.append('}')
                i += 2
                continue
            raise ValueError("stray '}}' at position {0}".format(i).replace("''", "'").replace("}}", "}"))
        else:
            result.append(c)
            i += 1
    return ''.join(result)

def peak_load(intervals: list[tuple[int, int]]) -> tuple[int, int]:
    events = []
    for s, e in intervals:
        events.append((s, 1))
        events.append((e, -1))
    events.sort(key=lambda x: (x[0], x[1]))
    current = 0
    max_load = 0
    earliest_t = 0
    i = 0
    n = len(events)
    while i < n:
        t = events[i][0]
        while i < n and events[i][0] == t:
            current += events[i][1]
            i += 1
        if current > max_load:
            max_load = current
            earliest_t = t
    return (max_load, earliest_t)

def apply_hunks(lines, hunks):
    ordered = sorted(hunks, key=lambda h: h[0])
    for i in range(1, len(ordered)):
        prev = ordered[i - 1]
        curr = ordered[i]
        if curr[0] == prev[0] or curr[0] < prev[0] + prev[1]:
            raise ValueError("conflicting hunks")
    result = list(lines)
    for start, delete, insert in reversed(ordered):
        if start < 0 or start + delete > len(lines):
            raise ValueError("hunk out of range")
        result[start:start + delete] = list(insert)
    return result

def count_locked_pairs(values: list[int], m: int) -> int:
    if m < 1:
        raise ValueError
    even = [0] * m
    odd = [0] * m
    for v in values:
        r = v % m
        if v & 1:
            odd[r] += 1
        else:
            even[r] += 1
    def pairs(cnt):
        res = 0
        for r in range(m):
            s = (m - r) % m
            if r < s:
                res += cnt[r] * cnt[s]
            elif r == s:
                res += cnt[r] * (cnt[r] - 1) // 2
        return res
    return pairs(even) + pairs(odd)

def min_insertions(s, allowed):
    allowed = set(allowed)
    n = len(s)
    if n <= 1:
        return 0
    INF = float('inf')
    dp = [[0] * n for _ in range(n)]
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if s[i] == s[j]:
                dp[i][j] = dp[i + 1][j - 1] if length > 2 else 0
            else:
                cand = INF
                if s[i] in allowed:
                    cand = min(cand, dp[i + 1][j] + 1)
                if s[j] in allowed:
                    cand = min(cand, dp[i][j - 1] + 1)
                dp[i][j] = cand
    res = dp[0][n - 1]
    return res if res < INF else -1

