def vector_norm(v: list[float]) -> float:
    for x in v:
        if math.isnan(x) or math.isinf(x):
            raise ValueError
    return math.hypot(*v)

class IntervalSet:
    def __init__(self):
        self._iv = []

    def add(self, lo, hi):
        if lo >= hi:
            raise ValueError
        out = []
        placed = False
        for a, b in self._iv:
            if b < lo:
                out.append((a, b))
            elif hi < a:
                if not placed:
                    out.append((lo, hi))
                    placed = True
                out.append((a, b))
            else:
                lo = min(lo, a)
                hi = max(hi, b)
        if not placed:
            out.append((lo, hi))
        self._iv = out

    def remove(self, lo, hi):
        if lo >= hi:
            raise ValueError
        out = []
        for a, b in self._iv:
            if b <= lo or hi <= a:
                out.append((a, b))
            else:
                if a < lo:
                    out.append((a, lo))
                if hi < b:
                    out.append((hi, b))
        self._iv = out

    def contains(self, x):
        for a, b in self._iv:
            if a <= x < b:
                return True
            if a > x:
                break
        return False

    def total(self):
        return sum(b - a for a, b in self._iv)

    def intervals(self):
        return list(self._iv)

    def gaps(self, lo, hi):
        if lo >= hi:
            raise ValueError
        out = []
        cur = lo
        for a, b in self._iv:
            if b <= cur:
                continue
            if a >= hi:
                break
            if a > cur:
                out.append((cur, min(a, hi)))
            cur = max(cur, b)
            if cur >= hi:
                break
        if cur < hi:
            out.append((cur, hi))
        return out

class MergeLedger:
    def __init__(self):
        self._parent = {}
        self._children = {}
        self._size = {}
        self._val = {}
        self._sum = {}
        self._history = []
        self._components = 0

    def add(self, x, value=0):
        if x in self._parent:
            raise ValueError(x)
        self._parent[x] = x
        self._children[x] = set()
        self._size[x] = 1
        self._val[x] = value
        self._sum[x] = value
        self._components += 1

    def _find(self, x):
        if x not in self._parent:
            raise KeyError(x)
        while self._parent[x] != x:
            x = self._parent[x]
        return x

    def merge(self, a, b):
        ra = self._find(a)
        rb = self._find(b)
        if ra == rb:
            return False
        if self._size[ra] < self._size[rb]:
            ra, rb = rb, ra
        self._parent[rb] = ra
        self._children[ra].add(rb)
        self._size[ra] += self._size[rb]
        self._sum[ra] += self._sum[rb]
        self._components -= 1
        self._history.append(rb)
        return True

    def same(self, a, b):
        return self.focus(a) == self.focus(b) if False else self._find(a) == self._find(b)

    def component_size(self, x):
        return self._size[self._find(x)]

    def component_value(self, x):
        return self._sum[self._find(x)]

    def add_value(self, x, delta):
        if x not in self._parent:
            raise KeyError(x)
        self._val[x] += delta
        self._sum[self._find(x)] += delta

    def components(self):
        return self._components

    def _subtree_sum(self, x):
        total = self._val[x]
        for c in self._children[x]:
            total += self._subtree_sum(c)
        return total

    def undo(self):
        if not self._history:
            raise RuntimeError("no merge to undo")
        rb = self._history.pop()
        ra = self._parent[rb]
        self._parent[rb] = rb
        self._children[ra].remove(rb)
        self._size[ra] -= self._size[rb]
        s = self._subtree_sum(rb)
        self._sum[ra] -= s
        self._sum[rb] = s
        self._components += 1

def weighted_median(values: list, weights: list) -> float:
    if len(values) != len(weights):
        raise ValueError("values and weights must have the same length")
    if any(w < 0 for w in weights):
        raise ValueError("weights must be >= 0")
    W = sum(weights)
    if W <= 0:
        raise ValueError("total weight must be > 0")
    pairs = sorted(zip(values, weights), key=lambda p: p[0])
    threshold = W / 2 - 1e-9
    cum = 0.0
    for v, w in pairs:
        cum += w
        if cum >= threshold:
            return v

def longest_spaced_repeat(s, gap):
    n = len(s)
    if n < 2:
        return 0
    dp = [[0] * n for _ in range(n)]
    ans = 0
    for i in range(n - 2, -1, -1):
        for j in range(n - 1, i, -1):
            if s[i] == s[j]:
                dp[i][j] = 1 + (dp[i + 1][j + 1] if j + 1 < n else 0)
            max_l = min(dp[i][j], j - i - gap)
            if max_l > ans:
                ans = max_l
    return ans

def longest_echo(s: str) -> int:
    n = len(s)
    if n < 2:
        return 0
    mod1, mod2 = 1_000_000_007, 1_000_000_009
    base = 911382323

    def check(L: int) -> bool:
        if L == 0:
            return True
        h1 = h2 = 0
        p1 = p2 = 1
        for i in range(L):
            h1 = (h1 * base + ord(s[i])) % mod1
            h2 = (h2 * base + ord(s[i])) % mod2
            if i < L - 1:
                p1 = (p1 * base) % mod1
                p2 = (p2 * base) % mod2
        seen = {(h1, h2)}
        for i in range(L, n):
            h1 = (h1 - ord(s[i - L]) * p1) % mod1
            h1 = (h1 * base + ord(s[i])) % mod1
            h2 = (h2 - ord(s[i - L]) * p2) % mod2
            h2 = (h2 * base + ord(s[i])) % mod2
            key = (h1, h2)
            if key in seen:
                return True
            seen.add(key)
        return False

    lo, hi, ans = 1, n - 1, 0
    while lo <= hi:
        mid = (lo + hi) // 2
        if check(mid):
            ans = mid
            lo = mid + 1
        else:
            hi = mid - 1
    return ans

def smallest_balanced(s):
    n = len(s)
    if n % 2 != 0:
        raise ValueError
    need_open = n // 2
    fixed_open = 0
    q = 0
    for c in s:
        if c == '(':
            fixed_open += 1
        elif c == '?':
            q += 1
    if fixed_open > need_open or fixed_open + q < need_open:
        raise ValueError
    need_q = need_open - fixed_open
    res = []
    for c in s:
        if c == '?':
            if need_q > 0:
                res.append('(')
                need_q -= 1
            else:
                res.append(')')
        else:
            res.append(c)
    bal = 0
    for c in res:
        bal += 1 if c == '(' else -1
        if bal < 0:
            raise ValueError
    if bal != 0:
        raise ValueError
    return ''.join(res)

def compute_balances(transactions):
    balances = {}
    for tx in transactions:
        amount = tx["amount"]
        parts = amount.split(".")
        if len(parts) > 2 or not parts[0].isdigit():
            raise ValueError("amount must be positive")
        if len(parts) == 2:
            if not parts[1].isdigit() or not (1 <= len(parts[1]) <= 2):
                raise ValueError("amount must be positive")
            cents = int(parts[0]) * 100 + int(parts[1].ljust(2, "0"))
        else:
            cents = int(parts[0]) * 100
        if cents <= 0:
            raise ValueError("amount must be positive")
        balances[tx["from"]] = balances.get(tx["from"], 0) - cents
        balances[tx["to"]] = balances.get(tx["to"], 0) + cents
    return balances

class Leaderboard:
    def __init__(self):
        self._best = {}
        self._achieved = {}
        self._seq = 0

    def submit(self, player, score):
        if player not in self._best or score > self._best[player]:
            self._best[player] = score
            self._achieved[player] = self._seq
            self._seq += 1
            return True
        return False

    def best(self, player):
        if player not in self._best:
            raise KeyError(player)
        return self._best[player]

    def rank(self, player):
        if player not in self._best:
            raise KeyError(player)
        b = self._best[player]
        return 1 + sum(1 for s in self._best.values() if s > b)

    def top(self, k):
        if k < 0:
            raise ValueError(k)
        ordered = sorted(
            self._best.keys(),
            key=lambda p: (-self._best[p], self._achieved[p]),
        )
        return [(p, self._best[p]) for p in ordered[:k]]

    def player_count(self):
        return len(self._best)

def round_robin(iterables: list):
    iterators = [iter(it) for it in iterables]
    while iterators:
        next_round = []
        for it in iterators:
            try:
                yield next(it)
                next_round.append(it)
            except StopIteration:
                pass
        iterators = next_round

def allocate_shares(total: int, weights: list) -> list[int]:
    if total < 0:
        raise ValueError("total must be >= 0")
    if not weights:
        raise ValueError("weights must be non-empty")
    if any(w < 0 for w in weights):
        raise ValueError("weights must be non-negative")
    W = sum(weights)
    if W == 0:
        raise ValueError("sum of weights must be > 0")
    n = len(weights)
    quotas = [total * w / W for w in weights]
    floors = [int(q) for q in quotas]
    remainders = [q - f for q, f in zip(quotas, floors)]
    result = floors[:]
    leftover = total - sum(floors)
    order = sorted(range(n), key=lambda i: (-remainders[i], i))
    for k in range(leftover):
        result[order[k]] += 1
    return result

from collections import OrderedDict

class TTLCache:
    def __init__(self, capacity):
        if not isinstance(capacity, int) or isinstance(capacity, bool) or capacity < 1:
            raise ValueError("capacity must be an integer >= 1")
        self.capacity = capacity
        self._data = OrderedDict()
        self._hits = 0
        self._misses = 0
        self._evictions = 0
        self._expirations = 0

    def _purge(self, now):
        dead = [k for k, (_, t, ttl) in self._data.items()
                if ttl is not None and now >= t + ttl]
        for k in dead:
            del self._data[k]
            self._expirations += 1

    def put(self, key, value, now, ttl=None):
        if ttl is not None and ttl <= 0:
            raise ValueError("ttl must be positive when not None")
        self._purge(now)
        if key in self._data:
            self._data[key] = (value, now, ttl)
            self._data.move_to_end(key)
        else:
            if len(self._data) >= self.capacity:
                self._data.popitem(last=False)
                self._evictions += 1
            self._data[key] = (value, now, ttl)

    def get(self, key, now):
        self._purge(now)
        if key in self._data:
            self._data.move_to_end(key)
            self._hits += 1
            return self._data[key][0]
        self._misses += 1
        return None

    def stats(self):
        return {
            "hits": self._hits,
            "misses": self._misses,
            "evictions": self._evictions,
            "expirations": self._expirations,
        }

    def __len__(self):
        return len(self._data)

def max_sessions(intervals, gap):
    if not intervals:
        return 0
    intervals = sorted(intervals, key=lambda x: x[1])
    count = 0
    last_end = -float('inf')
    for start, end in intervals:
        if start >= last_end + gap:
            count += 1
            last_end = end
    return count

def min_steps(grid, c):
    from collections import defaultdict, deque
    import math
    R, C = len(grid), len(grid[0])
    if grid[0][0] == -1 or grid[R - 1][C - 1] == -1:
        return -1
    DIRS = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    def bfs(sr, sc):
        dist = [[math.inf] * C for _ in range(R)]
        dist[sr][sc] = 0
        q = deque([(sr, sc)])
        while q:
            r, col = q.popleft()
            for dr, dc in DIRS:
                nr, nc = r + dr, col + dc
                if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] != -1 and dist[nr][nc] == math.inf:
                    dist[nr][nc] = dist[r][col] + 1
                    q.append((nr, nc))
        return dist
    distS = bfs(0, 0)
    distE = bfs(R - 1, C - 1)
    pure = distS[R - 1][C - 1]
    groups = defaultdict(lambda: ([], []))
    for r in range(R):
        for col in range(C):
            val = grid[r][col]
            if val != -1:
                groups[val][0].append(distS[r][col])
                groups[val][1].append(distE[r][col])
    def min_cross(ds, de):
        min_de = min(de)
        count = 0
        for d in de:
            if d == min_de:
                count += 1
                if count >= 2:
                    break
        if count >= 2:
            return min(ds) + min_de
        min_ds_other = math.inf
        ds_minde = math.inf
        second_de = math.inf
        for dss, dee in zip(ds, de):
            if dee == min_de:
                ds_minde = dss
            else:
                if dss < min_ds_other:
                    min_ds_other = dss
                if dee < second_de:
                    second_de = dee
        return min(min_ds_other + min_de, ds_minde + second_de)
    min_tele = math.inf
    for ds_list, de_list in groups.values():
        if len(ds_list) >= 2:
            cross = min_cross(ds_list, de_list)
            if cross < min_tele:
                min_tele = cross
    ans = min(pure, min_tele + c)
    return ans if ans < math.inf else -1

def best_circular_selection(values, k):
    n = len(values)
    if k == 0:
        return 0
    NEG = -10**18

    def linear(arr, m):
        ln = len(arr)
        if m == 0:
            return 0
        if m < 0 or ln == 0 or m > (ln + 1) // 2:
            return NEG
        dp = [[NEG] * (m + 1) for _ in range(ln + 1)]
        for i in range(ln + 1):
            dp[i][0] = 0
        for i in range(1, ln + 1):
            for j in range(1, min(m, (i + 1) // 2) + 1):
                dp[i][j] = dp[i - 1][j]
                prev = dp[i - 2][j - 1] if i >= 2 else (0 if j == 1 else NEG)
                if prev > NEG // 2:
                    cand = prev + arr[i - 1]
                    if cand > dp[i][j]:
                        dp[i][j] = cand
        return dp[ln][m]

    best = NEG
    # case 1: skip first
    s1 = linear(values[1:], k)
    if s1 > best:
        best = s1
    # case 2: take first (implies skip last)
    if k >= 1:
        s2 = values[0] + linear(values[2:n - 1] if n > 1 else [], k - 1)
        if s2 > best:
            best = s2
    if best <= NEG // 2:
        raise ValueError("no valid selection")
    return int(best)

def kth_root_floor(n: int, k: int) -> int:
    if n < 0 or k < 1:
        raise ValueError
    if n <= 1 or k == 1:
        return n
    if k >= n.bit_length():
        return 1
    low = 1
    high = 1 << ((n.bit_length() + k - 1) // k)
    while low < high:
        mid = (low + high + 1) // 2
        if mid ** k <= n:
            low = mid
        else:
            high = mid - 1
    return low

def parse_duration(text):
    if not isinstance(text, str):
        raise TypeError("expected str")
    if len(text) == 0 or text.isspace():
        raise ValueError("empty duration")
    i = 0
    n = len(text)
    last_order = -1
    total = 0
    units = {'h': (0, 3600), 'm': (1, 60), 's': (2, 1)}
    seen = set()
    while i < n:
        if not ('0' <= text[i] <= '9'):
            raise ValueError("malformed duration")
        start = i
        while i < n and '0' <= text[i] <= '9':
            i += 1
        if i == n:
            raise ValueError("malformed duration")
        unit = text[i]
        if unit not in units:
            raise ValueError("malformed duration")
        end_digits = i
        i += 1
        if unit in seen:
            raise ValueError("malformed duration")
        order, mult = units[unit]
        if order <= last_order:
            raise ValueError("malformed duration")
        seen.add(unit)
        last_order = order
        total += int(text[start:end_digits]) * mult
    return total

from collections import defaultdict

def count_pulses(deltas: list[int], k: int, lo: int, hi: int) -> int:
    n = len(deltas)
    if not (1 <= lo <= hi <= n):
        raise ValueError
    pref = [0] * (n + 1)
    for i in range(n):
        pref[i + 1] = (pref[i] + deltas[i]) % k
    freq = defaultdict(int)
    count = 0
    add_up_to = 0
    remove_up_to = 0
    for j in range(n + 1):
        while remove_up_to < j - hi:
            freq[pref[remove_up_to]] -= 1
            remove_up_to += 1
        while add_up_to <= j - lo:
            freq[pref[add_up_to]] += 1
            add_up_to += 1
        if j >= lo:
            count += freq[pref[j]]
    return count

import unicodedata

def truncate_display(s: str, width: int) -> str:
    if width < 0:
        raise ValueError("width must be >= 0")
    if width == 0 or not s:
        return ""

    def is_combining(ch: str) -> bool:
        return unicodedata.category(ch) in ("Mn", "Mc", "Me")

    units = []
    current = []
    for ch in s:
        if not current:
            current.append(ch)
        elif is_combining(ch):
            current.append(ch)
        else:
            units.append("".join(current))
            current = [ch]
    if current:
        units.append("".join(current))

    if width >= len(units):
        return s
    return "".join(units[:width])

def flatten_depth(nested, max_depth):
    if not isinstance(nested, list):
        raise TypeError("nested must be a list")
    if isinstance(max_depth, bool) or not isinstance(max_depth, int):
        raise TypeError("max_depth must be an int")
    if max_depth < 0:
        raise ValueError("max_depth must be >= 0")
    result = []
    stack = [(nested, max_depth, 0)]
    while stack:
        lst, rem, idx = stack[-1]
        if idx >= len(lst):
            stack.pop()
            continue
        stack[-1] = (lst, rem, idx + 1)
        elem = lst[idx]
        if rem > 0 and isinstance(elem, list):
            stack.append((elem, rem - 1, 0))
        else:
            result.append(elem)
    return result

class CountingBag:
    def __init__(self):
        self._counts = {}
        self._entry = {}
        self._moment = 0
        self._total = 0

    def add(self, item) -> int:
        if item not in self._counts:
            self._moment += 1
            self._entry[item] = self._moment
            self._counts[item] = 0
        self._counts[item] += 1
        self._total += 1
        return self._counts[item]

    def discard(self, item) -> bool:
        if item not in self._counts:
            return False
        self._counts[item] -= 1
        self._total -= 1
        if self._counts[item] == 0:
            del self._counts[item]
            del self._entry[item]
        return True

    def count(self, item) -> int:
        return self._counts.get(item, 0)

    def __len__(self) -> int:
        return self._total

    def distinct(self) -> int:
        return len(self._counts)

    def most_common(self, k) -> list:
        if k < 0:
            raise ValueError("k must be non-negative")
        if k == 0:
            return []
        items = sorted(
            self._counts.items(),
            key=lambda x: (-x[1], self._entry[x[0]]),
        )
        return items[:k]

def rank_scores(scores: list) -> list[int]:
    if not scores:
        return []
    for s in scores:
        if s != s:
            raise ValueError("NaN scores are not allowed")
    return [1 + sum(1 for t in scores if t > s) for s in scores]

def clamp_values(values, low, high):
    if not isinstance(values, list):
        raise TypeError("values must be a list")
    if (isinstance(low, bool) or not isinstance(low, (int, float)) or
            isinstance(high, bool) or not isinstance(high, (int, float))):
        raise TypeError("bounds must be numbers")
    if low > high:
        raise ValueError("low must not exceed high")
    result = []
    for i, v in enumerate(values):
        if isinstance(v, bool) or not isinstance(v, (int, float)):
            raise TypeError("index {}".format(i))
        if v < low:
            result.append(low)
        elif v > high:
            result.append(high)
        else:
            result.append(v)
    return result

import heapq
from collections import defaultdict

def min_cost_route(n, edges, s, t, switch_cost):
    if s == t:
        return 0
    graph = [defaultdict(list) for _ in range(n)]
    for u, v, w, c in edges:
        graph[u][c].append((v, w))
        if u != v:
            graph[v][c].append((u, w))
    pq = []
    dist = {}
    settled = set()
    for c, neighs in graph[s].items():
        for v, w in neighs:
            state = (v, c)
            if w < dist.get(state, float('inf')):
                dist[state] = w
                heapq.heappush(pq, (w, v, c))
    while pq:
        cost, u, col = heapq.heappop(pq)
        state = (u, col)
        if state in settled:
            continue
        settled.add(state)
        if u == t:
            return cost
        if col is None:
            for c, neighs in graph[u].items():
                for v, w in neighs:
                    new_cost = cost + switch_cost + w
                    nstate = (v, c)
                    if new_cost < dist.get(nstate, float('inf')):
                        dist[nstate] = new_cost
                        heapq.heappush(pq, (new_cost, v, c))
        else:
            nstate = (u, None)
            if cost < dist.get(nstate, float('inf')):
                dist[nstate] = cost
                heapq.heappush(pq, (cost, u, None))
            if col in graph[u]:
                for v, w in graph[u][col]:
                    new_cost = cost + w
                    nstate = (v, col)
                    if new_cost < dist.get(nstate, float('inf')):
                        dist[nstate] = new_cost
                        heapq.heappush(pq, (new_cost, v, col))
    return -1

def summarize_by_category(rows):
    if not isinstance(rows, list):
        raise TypeError("rows must be a list")
    result = {}
    order = []
    for i, row in enumerate(rows):
        if not isinstance(row, tuple) or len(row) != 3:
            raise TypeError(f"row {i}")
        category, amount, refunded = row
        if not isinstance(category, str) or category == "":
            raise ValueError(f"row {i}")
        if isinstance(amount, bool) or not isinstance(amount, (int, float)):
            raise TypeError(f"row {i}")
        if amount < 0:
            raise ValueError(f"row {i}")
        if not isinstance(refunded, bool):
            raise TypeError(f"row {i}")
        if category not in result:
            order.append(category)
            result[category] = {"count": 0, "gross": 0.0, "net": 0.0, "largest": float(amount)}
        s = result[category]
        s["count"] = s["count"] + 1
        amt = float(amount)
        s["gross"] = s["gross"] + amt
        if not refunded:
            s["net"] = s["net"] + amt
        if amt > s["largest"]:
            s["largest"] = amt
    return {cat: result[cat] for cat in order}

def resolve_build_order(deps):
    graph = {}
    for pkg, ds in deps.items():
        graph.setdefault(pkg, set())
        for d in ds:
            graph.setdefault(d, set())
            graph[pkg].add(d)
    order = []
    visiting = set()
    visited = set()

    def visit(node):
        if node in visiting:
            raise ValueError("dependency cycle detected at " + node)
        if node in visited:
            return
        visiting.add(node)
        for dep in sorted(graph[node]):
            visit(dep)
        visiting.remove(node)
        visited.add(node)
        order.append(node)

    for node in sorted(graph):
        visit(node)
    return order

import heapq

def max_bounty(jobs: list[tuple[int, int]], cap: int) -> int:
    if cap < 1:
        raise ValueError
    if not jobs:
        return 0
    jobs = sorted(jobs, key=lambda x: x[0])
    heap: list[int] = []
    total = 0
    for d, p in jobs:
        if len(heap) < cap * d:
            heapq.heappush(heap, p)
            total += p
        elif p > heap[0]:
            total += p - heap[0]
            heapq.heapreplace(heap, p)
    return total
